#!/usr/bin/env python3
"""Twig: a rendering engine for a small subset of HTML and CSS."""

import math
import re
import sys


# ---------------------------------------------------------------------------
# Rule 1 helpers
# ---------------------------------------------------------------------------

def parse_length(s):
    """Parse a length string. Returns int or None if invalid (negative)."""
    s = s.strip()
    if s.endswith('px'):
        s = s[:-2]
    try:
        v = int(s)
    except ValueError:
        return None
    if v < 0:
        return None  # Rule 2: negative is invalid
    return v


# ---------------------------------------------------------------------------
# HTML Parser
# ---------------------------------------------------------------------------

ENTITY_MAP = {
    'amp': '&',
    'lt': '<',
    'gt': '>',
    'quot': '"',
    'apos': "'",
    'nbsp': '\xa0',
}

VOID_ELEMENTS = frozenset([
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr',
])


def decode_entities(s):
    """Decode HTML entities in text content."""
    result = []
    i = 0
    while i < len(s):
        if s[i] == '&' and i + 1 < len(s):
            # Try numeric &#NNN;
            if s[i + 1] == '#':
                j = i + 2
                num_str = ''
                while j < len(s) and s[j] != ';':
                    if s[j].isdigit():
                        num_str += s[j]
                    j += 1
                if j < len(s) and s[j] == ';' and num_str:
                    try:
                        code = int(num_str)
                        result.append(chr(code))
                    except (ValueError, OverflowError):
                        result.append(s[i:j + 1])
                    i = j + 1
                    continue
                else:
                    result.append(s[i])
                    i += 1
                    continue
            else:
                # Named entity
                j = i + 1
                while j < len(s) and s[j] != ';':
                    if s[j].isalpha():
                        j += 1
                    else:
                        break
                if j < len(s) and s[j] == ';':
                    name = s[i + 1:j]
                    if name in ENTITY_MAP:
                        result.append(ENTITY_MAP[name])
                    else:
                        result.append(s[i:j + 1])
                    i = j + 1
                    continue
                else:
                    result.append(s[i])
                    i += 1
                    continue
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)


class Element:
    __slots__ = ('tag', 'attrs', 'children', 'text')

    def __init__(self, tag, attrs=None, children=None, text=None):
        self.tag = tag
        self.attrs = attrs or {}
        self.children = children or []
        self.text = text


def parse_html(html_text):
    """Parse HTML into a tree of Elements."""
    # Remove comments and DOCTYPE
    html_text = re.sub(r'<!--.*?-->', '', html_text, flags=re.DOTALL)
    html_text = re.sub(r'<!DOCTYPE[^>]*>', '', html_text, flags=re.IGNORECASE)

    pos = [0]  # mutable index

    def parse_children():
        elements = []
        while pos[0] < len(html_text):
            ch, new_pos = _parse_node(html_text, pos)
            if ch is None:
                break
            elements.append(ch)
        return elements

    def _parse_node(text, p):
        # Text node
        idx = text.find('<', p[0])
        if idx == -1:
            raw = text[p[0]:]
            return Element('_text_', text=decode_entities(raw)), len(text)

        if idx != p[0]:
            raw = text[p[0]:idx]
            return Element('_text_', text=decode_entities(raw)), idx

        # We're at a '<'
        rest = text[idx + 1:]

        if rest.startswith('/'):
            # End tag - return sentinel to signal closing
            m = re.match(r'([a-z]+)\s*>', rest, re.IGNORECASE)
            if m:
                return ('_end_', m.group(1)), idx + 1 + m.end()
            return None, idx + 1

        if rest.startswith('!'):
            # Comment or doctype already removed, but handle stray
            end = text.find('>', idx + 1)
            if end == -1:
                return None, len(text)
            return None, end + 1

        # Start tag
        m = re.match(r'([a-z]+)(\s*)(.*)', rest, re.DOTALL | re.IGNORECASE)
        if not m:
            return None, idx + 1

        tag = m.group(1).lower()
        attrs = {}
        rest_attrs = m.group(3).rstrip('/')
        if rest_attrs.strip():
            attrs = _parse_attrs(rest_attrs)

        if tag in VOID_ELEMENTS:
            return Element(tag, attrs=attrs), idx + 1 + len(m.group(0))

        # Check for self-closing / empty content
        end_idx = text.find(f'</{tag}>', idx + 1)
        if end_idx == -1:
            # Unclosed - take everything to end
            child_end = len(text)
        else:
            child_end = end_idx

        children = parse_children_between(idx + 1 + len(m.group(0)), end_idx)
        close_tag_len = len(f'</{tag}>')
        return Element(tag, attrs=attrs, children=children), child_end + close_tag_len

    def parse_children_between(start, end):
        elements = []
        p = start
        open_stack = []
        while p < end:
            ch, new_p = _parse_node_with_closing(html_text, p, open_stack, end)
            if ch is None:
                break
            if isinstance(ch, tuple) and ch[0] == '_end_':
                # This end tag was consumed by the parser
                open_stack.pop() if open_stack else None
                continue
            elements.append(ch)
        return elements

    def _parse_node_with_closing(text, p, open_stack, end_limit):
        if p >= end_limit:
            return None, end_limit

        idx = text.find('<', p)
        if idx == -1 or idx > end_limit:
            raw = text[p:end_limit]
            return Element('_text_', text=decode_entities(raw)), end_limit

        if idx != p:
            raw = text[p:idx]
            return Element('_text_', text=decode_entities(raw)), idx

        rest = text[idx + 1:]

        if rest.startswith('/'):
            m = re.match(r'([a-z]+)\s*>', rest, re.IGNORECASE)
            if m:
                end_tag = m.group(1).lower()
                # Find matching open element
                found = False
                for i in range(len(open_stack) - 1, -1, -1):
                    if open_stack[i][0] == end_tag:
                        found = True
                        break
                if not found:
                    # Stray end tag - ignore
                    return None, idx + 1 + m.end()
                # Close from this point
                return ('_end_', end_tag), idx + 1 + m.end()
            return None, idx + 1

        if rest.startswith('!'):
            end = text.find('>', idx + 1)
            if end == -1:
                return None, len(text)
            return None, end + 1

        # Start tag
        m = re.match(r'([a-z]+)(\s*)(.*)', rest, re.DOTALL | re.IGNORECASE)
        if not m:
            return None, idx + 1

        tag = m.group(1).lower()
        attrs = {}
        rest_attrs = m.group(3).rstrip('/')
        if rest_attrs.strip():
            attrs = _parse_attrs(rest_attrs)

        if tag in VOID_ELEMENTS:
            return Element(tag, attrs=attrs), idx + 1 + len(m.group(0))

        # Push onto stack
        open_stack.append((tag, idx))

        # Check for implicit closing (<p> closes <p>, <li> closes <li>)
        if tag in ('p', 'li'):
            # Check if there's already an open element with same name
            for i in range(len(open_stack) - 2, -1, -1):
                if open_stack[i][0] == tag:
                    # Close it implicitly
                    close_end = open_stack[i][1]
                    # Parse children up to here
                    children = parse_children_between(p + 1 + len(m.group(0)), close_end)
                    elem = Element(tag, attrs=attrs, children=children)
                    del open_stack[i + 1:]
                    return elem, close_end + len(f'</{tag}>')

        # Look for matching end tag
        end_tag_pos = text.find(f'</{tag}>', idx + 1)
        if end_tag_pos == -1:
            # Unclosed - take to end
            children = parse_children_between(p + 1 + len(m.group(0)), len(text))
            return Element(tag, attrs=attrs, children=children), len(text)

        children = parse_children_between(p + 1 + len(m.group(0)), end_tag_pos)
        return Element(tag, attrs=attrs, children=children), end_tag_pos + len(f'</{tag}>')

    root = Element('root')
    root.children = parse_children()
    return root


def _parse_attrs(s):
    """Parse attribute string into dict."""
    attrs = {}
    pattern = re.compile(r'''(\S+)(?:=(?:"([^"]*)"|'([^']*)'|(\S+)))?''')
    for m in pattern.finditer(s):
        name = m.group(1).lower()
        if m.group(2) is not None:
            val = m.group(2)
        elif m.group(3) is not None:
            val = m.group(3)
        elif m.group(4) is not None:
            val = m.group(4)
        else:
            val = ''
        attrs[name] = decode_entities(val)
    return attrs


def parse_children_between(start, end):
    """Parse children between positions in html_text."""
    elements = []
    p = start
    open_stack = []
    while p < end:
        ch, new_p = _parse_node_with_closing(html_text, p, open_stack, end)
        if ch is None:
            break
        if isinstance(ch, tuple) and ch[0] == '_end_':
            open_stack.pop() if open_stack else None
            continue
        elements.append(ch)
    return elements


html_text = None  # global reference for nested parsing


def parse_html_v2(html_text_str):
    """Parse HTML into a tree of Elements using a simpler approach."""
    global html_text
    html_text = html_text_str

    # Remove comments and DOCTYPE
    html_text = re.sub(r'<!--.*?-->', '', html_text, flags=re.DOTALL)
    html_text = re.sub(r'<!DOCTYPE[^>]*>', '', html_text, flags=re.IGNORECASE)

    root = Element('root')
    root.children = _parse_children(0, len(html_text), [])
    return root


def _parse_children(start, end, open_stack):
    """Parse children from position start to end."""
    elements = []
    p = start
    while p < end:
        ch, new_p = _parse_one(html_text, p, open_stack, end)
        if ch is None:
            break
        if isinstance(ch, tuple) and ch[0] == '_end_':
            if open_stack:
                open_stack.pop()
            continue
        elements.append(ch)
    return elements


def _parse_one(text, p, open_stack, end_limit):
    if p >= end_limit:
        return None, end_limit

    idx = text.find('<', p)
    if idx == -1 or idx > end_limit:
        raw = text[p:end_limit]
        return Element('_text_', text=decode_entities(raw)), end_limit

    if idx != p:
        raw = text[p:idx]
        return Element('_text_', text=decode_entities(raw)), idx

    rest = text[idx + 1:]

    if rest.startswith('/'):
        m = re.match(r'([a-z]+)\s*>', rest, re.IGNORECASE)
        if m:
            end_tag = m.group(1).lower()
            found = False
            for i in range(len(open_stack) - 1, -1, -1):
                if open_stack[i][0] == end_tag:
                    found = True
                    break
            if not found:
                return None, idx + 1 + m.end()
            return ('_end_', end_tag), idx + 1 + m.end()
        return None, idx + 1

    if rest.startswith('!'):
        end = text.find('>', idx + 1)
        if end == -1:
            return None, len(text)
        return None, end + 1

    m = re.match(r'([a-z]+)(\s*)(.*)', rest, re.DOTALL | re.IGNORECASE)
    if not m:
        return None, idx + 1

    tag = m.group(1).lower()
    attrs = {}
    rest_attrs = m.group(3).rstrip('/')
    if rest_attrs.strip():
        attrs = _parse_attrs(rest_attrs)

    if tag in VOID_ELEMENTS:
        return Element(tag, attrs=attrs), idx + 1 + len(m.group(0))

    # Check for implicit closing
    if tag in ('p', 'li'):
        for i in range(len(open_stack) - 2, -1, -1):
            if open_stack[i][0] == tag:
                close_end = open_stack[i][1]
                children = _parse_children(p + 1 + len(m.group(0)), close_end, open_stack)
                elem = Element(tag, attrs=attrs, children=children)
                del open_stack[i + 1:]
                return elem, close_end + len(f'</{tag}>')

    open_stack.append((tag, idx))

    end_tag_pos = text.find(f'</{tag}>', idx + 1)
    if end_tag_pos == -1:
        children = _parse_children(p + 1 + len(m.group(0)), len(text), open_stack)
        return Element(tag, attrs=attrs, children=children), len(text)

    children = _parse_children(p + 1 + len(m.group(0)), end_tag_pos, open_stack)
    return Element(tag, attrs=attrs, children=children), end_tag_pos + len(f'</{tag}>')


# ---------------------------------------------------------------------------
# CSS Parser
# ---------------------------------------------------------------------------

def parse_css(css_text):
    """Parse CSS text into list of (selector_string, [(prop, value)]) tuples."""
    # Remove comments
    css_text = re.sub(r'/\*.*?\*/', '', css_text, flags=re.DOTALL)
    rules = []
    # Match selector { declarations }
    pattern = re.compile(r'([^{}]+)\{([^{}]*)\}')
    for m in pattern.finditer(css_text):
        selector_str = m.group(1).strip()
        decl_str = m.group(2).strip()
        declarations = _parse_declarations(decl_str)
        # Split selector list by comma
        selectors = [s.strip() for s in selector_str.split(',')]
        for sel in selectors:
            if sel and _validate_selector(sel):
                rules.append((sel, declarations))
    return rules


def _validate_selector(sel):
    """Check if a selector can be parsed."""
    try:
        _parse_selector_parts(sel)
        return True
    except Exception:
        return False


def _parse_selector_parts(sel):
    """Parse a single compound selector."""
    sel = sel.strip()
    if sel == '*':
        return
    # Must match: optional tag, then .class/#id parts
    pattern = re.compile(r'^([a-z]*)((?:\.[a-zA-Z_][a-zA-Z0-9_-]*)*(?:#[a-zA-Z_][a-zA-Z0-9_-]*)*)$')
    m = pattern.match(sel)
    if not m:
        raise ValueError(f"Invalid selector: {sel}")


def _parse_declarations(decl_str):
    """Parse declarations from a rule body."""
    decls = []
    parts = decl_str.split(';')
    for part in parts:
        part = part.strip()
        if not part:
            continue
        colon = part.find(':')
        if colon == -1:
            continue
        prop = part[:colon].strip().lower()
        val = part[colon + 1:].strip()
        important = False
        if val.endswith('!important'):
            val = val[:-len('!important')].strip()
            important = True
        decls.append((prop, val, important))
    return decls


# Specificity calculation
def specificity(selector_str):
    """Calculate specificity as (ids, classes, tags)."""
    sel = selector_str.strip()
    if sel == '*':
        return (0, 0, 0)
    ids = len(re.findall(r'#', sel))
    classes = len(re.findall(r'\.', sel))
    # Tags: non-* word tokens
    tags = len(re.findall(r'[a-z][a-z0-9]*', sel))
    return (ids, classes, tags)


# ---------------------------------------------------------------------------
# Cascade & Style Resolution
# ---------------------------------------------------------------------------

BLOCK_TAGS = frozenset([
    'body', 'div', 'p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
    'ul', 'ol', 'li', 'section', 'article', 'header', 'footer', 'main', 'blockquote',
])

KNOWN_PROPERTIES = {
    'display', 'width', 'height', 'font-size',
    'margin-top', 'margin-right', 'margin-bottom', 'margin-left',
    'padding-top', 'padding-right', 'padding-bottom', 'padding-left',
    'border-width',
}

SHORTHAND_MAP = {
    'margin': ('margin-top', 'margin-right', 'margin-bottom', 'margin-left'),
    'padding': ('padding-top', 'padding-right', 'padding-bottom', 'padding-left'),
    'border-width': ('border-width', 'border-width', 'border-width', 'border-width'),
}


def resolve_styles(root):
    """Apply styles to all elements. Returns the body element or None."""
    # Collect all style rules from <style> elements
    css_rules = []
    for el in walk_elements(root):
        if el.tag == 'style':
            css_text = ''
            for child in el.children:
                if child.tag == '_text_':
                    css_text += child.text
            css_rules.extend(parse_css(css_text))

    # For each element, compute its computed styles
    for el in walk_elements(root):
        if el.tag == '_text_' or el.tag == 'style' or el.tag == 'script':
            continue
        _apply_styles(el, css_rules)


def walk_elements(el):
    """Yield all elements in document order."""
    yield el
    for child in el.children:
        if isinstance(child, Element):
            yield from walk_elements(child)


def _apply_styles(el, css_rules):
    """Compute computed styles for an element."""
    styles = {}

    # Get inline styles
    inline_decls = []
    if 'style' in el.attrs:
        inline_decls = _parse_declarations(el.attrs['style'])

    # Get matching CSS rules
    matching = []
    for sel_str, decls in css_rules:
        if _matches(el, sel_str):
            spec = specificity(sel_str)
            for prop, val, important in decls:
                if prop not in KNOWN_PROPERTIES:
                    continue
                matching.append((important, spec, len(matching), prop, val))

    # Combine inline and CSS
    all_candidates = []
    for prop, val, important in inline_decls:
        if prop not in KNOWN_PROPERTIES:
            continue
        # Inline styles have highest priority unless !important on CSS
        all_candidates.append((True, (0, 0, 0), -1, prop, val, True))  # source=inline, important flag

    for important, spec, order, prop, val in matching:
        all_candidates.append((False, spec, order, prop, val, important))

    # Resolve per property
    props_seen = set()
    for candidate in reversed(all_candidates):
        _, _, _, prop, val, is_inline = candidate
        if prop in props_seen:
            continue
        props_seen.add(prop)

        parsed_val = _parse_value(prop, val)
        if parsed_val is not None:
            styles[prop] = parsed_val

    # Handle shorthand properties
    for short, long_props in SHORTHAND_MAP.items():
        if short in styles:
            for lp, sp in zip(long_props, styles[short]):
                styles[lp] = sp
            # Remove shorthand
            del styles[short]

    # Set defaults
    if 'display' not in styles:
        styles['display'] = 'block' if el.tag in BLOCK_TAGS else 'inline'
    if 'width' not in styles:
        styles['width'] = 'auto'
    if 'height' not in styles:
        styles['height'] = 'auto'
    for side in ('top', 'right', 'bottom', 'left'):
        for prefix in ('margin-', 'padding-', 'border-'):
            key = f'{prefix}{side}'
            if key not in styles:
                styles[key] = 0
    if 'font-size' not in styles:
        styles['font-size'] = None  # Will inherit

    el.styles = styles


def _parse_value(prop, val_str):
    """Parse a CSS value. Returns int for lengths, string for keywords, None if invalid."""
    val_str = val_str.strip()

    if prop == 'display':
        if val_str in ('block', 'inline', 'none'):
            return val_str
        return None

    if prop in ('width', 'height'):
        if val_str == 'auto':
            return 'auto'
        v = parse_length(val_str)
        return v

    if prop == 'font-size':
        v = parse_length(val_str)
        return v

    # Margin, padding, border-width: one to four lengths
    if prop in SHORTHAND_MAP.values():
        v = parse_length(val_str)
        return v

    return None


def _matches(el, selector_str):
    """Check if an element matches a simple descendant selector."""
    parts = selector_str.split()
    # Reverse so last part matches the element
    for i in range(len(parts)):
        part = parts[-(i + 1)]
        if i == 0:
            if not _matches_compound(el, part):
                return False
        else:
            # Must find ancestor
            found = False
            parent = _parent(el)
            while parent:
                if _matches_compound(parent, part):
                    found = True
                    break
                parent = _parent(parent)
            if not found:
                return False
    return True


def _parent(el):
    """Find parent of an element."""
    # We need to track parents during tree building
    return getattr(el, '_parent_', None)


def _matches_compound(el, compound):
    """Match a compound selector against an element."""
    if compound == '*':
        return True

    m = re.match(r'^([a-z]*)((?:\.[a-zA-Z_][a-zA-Z0-9_-]*)*(?:#[a-zA-Z_][a-zA-Z0-9_-]*)*)$', compound)
    if not m:
        return False

    tag_part = m.group(1)
    class_id_part = m.group(2)

    if tag_part and el.tag != tag_part:
        return False

    # Check classes and ids
    if class_id_part:
        classes = re.findall(r'\.([a-zA-Z_][a-zA-Z0-9_-]*)', class_id_part)
        ids = re.findall(r'#([a-zA-Z_][a-zA-Z0-9_-]*)', class_id_part)
        for c in classes:
            if c not in el.attrs.get('class', '').split():
                return False
        for id_val in ids:
            if el.attrs.get('id') != id_val:
                return False

    return True


# ---------------------------------------------------------------------------
# Layout Engine
# ---------------------------------------------------------------------------

class Box:
    __slots__ = ('tag', 'x', 'y', 'width', 'height', 'styles', 'children', 'lines')

    def __init__(self, tag, x=0, y=0, width=0, height=0):
        self.tag = tag
        self.x = x
        self.y = y
        self.width = width
        self.height = height
        self.styles = {}
        self.children = []  # Block boxes
        self.lines = []  # Line boxes (for blocks)


class LineBox:
    __slots__ = ('x', 'y', 'width', 'height', 'text')

    def __init__(self, x, y, width, height, text=''):
        self.x = x
        self.y = y
        self.width = width
        self.height = height
        self.text = text


def layout_document(root, viewport_width=800):
    """Layout the document and return box tree."""
    body_el = _find_body(root)
    if body_el is None:
        return None

    body_box = Box('body')
    body_box.styles = body_el.styles

    # Layout body
    _layout_block(body_box, viewport_width)

    return body_box


def _find_body(root):
    """Find the body element."""
    for el in walk_elements(root):
        if el.tag == 'body':
            return el
    return None


def _layout_block(box, containing_width):
    """Layout a block box: position children, compute sizes."""
    styles = box.styles
    margin_top = styles.get('margin-top', 0)
    margin_right = styles.get('margin-right', 0)
    margin_bottom = styles.get('margin-bottom', 0)
    margin_left = styles.get('margin-left', 0)
    padding_top = styles.get('padding-top', 0)
    padding_right = styles.get('padding-right', 0)
    padding_bottom = styles.get('padding-bottom', 0)
    padding_left = styles.get('padding-left', 0)
    border_top = styles.get('border-width', 0)
    border_right = styles.get('border-width', 0)
    border_bottom = styles.get('border-width', 0)
    border_left = styles.get('border-width', 0)

    display = styles.get('display', 'block')
    if display == 'none':
        return

    # Get content width
    content_width_spec = styles.get('width', 'auto')
    if content_width_spec == 'auto':
        available = containing_width - margin_left - margin_right
        content_w = max(0, available - padding_left - border_left - padding_right - border_right)
    else:
        content_w = content_width_spec

    # Position the box
    box.x = margin_left + border_left + padding_left
    box.y = margin_top + border_top + padding_top
    box.width = content_w

    # Layout children
    block_children = []
    for child_el in box._element_.children:
        if child_el.tag == '_text_':
            continue
        if child_el.styles.get('display') == 'none':
            continue
        block_children.append(child_el)

    if not block_children:
        box.height = 0
        return

    # Compute font-size for the block (used for space width)
    font_size = styles.get('font-size', 16)
    if font_size is None:
        # Inherit from parent
        font_size = _get_inherited_font_size(box._element_)
        box.styles['font-size'] = font_size

    # Layout inline content for this block
    _layout_inline(box, block_children, font_size, content_w)

    # Now layout child blocks
    child_y = margin_top + border_top + padding_top  # content top relative to box

    for i, child_el in enumerate(block_children):
        child_box = Box(child_el.tag)
        child_box.styles = child_el.styles
        child_box._element_ = child_el

        # Position child
        child_margin_top = child_el.styles.get('margin-top', 0)
        child_border_top = child_el.styles.get('border-width', 0)
        child_padding_top = child_el.styles.get('padding-top', 0)

        if i == 0:
            # First child: margin edge sits at parent content top
            child_box.y = child_y + child_margin_top + child_border_top + child_padding_top
        else:
            # Later children: border edge below previous border edge
            prev = block_children[i - 1]
            prev_margin_bottom = prev.styles.get('margin-bottom', 0)
            prev_border_bottom = prev.styles.get('border-width', 0)
            gap = max(prev_margin_bottom, child_margin_top)
            prev_content_top = prev.y - prev.styles.get('margin-top', 0) - prev.styles.get('border-width', 0)
            prev_border_bottom_edge = prev_content_top + prev.height + prev.styles.get('border-width', 0)
            child_box.y = prev_border_bottom_edge + gap + child_border_top + child_padding_top

        child_box.x = box.x + child_margin_top  # wrong... should use margin-left

    # Actually let me redo this more carefully
    pass


# Let me rewrite the layout more carefully
def layout_document_v2(root, viewport_width=800):
    """Layout the document and return box tree."""
    body_el = _find_body(root)
    if body_el is None:
        return None

    body_box = Box('body')
    body_box.styles = body_el.styles
    body_box._element_ = body_el

    # Body starts at 0,0
    body_box.y = 0

    # Layout body
    _layout_block_v2(body_box, viewport_width)

    return body_box


def _layout_block_v2(box, containing_width):
    """Layout a block box: position children, compute sizes."""
    styles = box.styles
    display = styles.get('display', 'block')
    if display == 'none':
        return

    margin_top = styles.get('margin-top', 0)
    margin_right = styles.get('margin-right', 0)
    margin_bottom = styles.get('margin-bottom', 0)
    margin_left = styles.get('margin-left', 0)
    padding_top = styles.get('padding-top', 0)
    padding_right = styles.get('padding-right', 0)
    padding_bottom = styles.get('padding-bottom', 0)
    padding_left = styles.get('padding-left', 0)
    border_top = styles.get('border-width', 0)
    border_right = styles.get('border-width', 0)
    border_bottom = styles.get('border-width', 0)
    border_left = styles.get('border-width', 0)

    # Content width
    content_width_spec = styles.get('width', 'auto')
    if content_width_spec == 'auto':
        available = containing_width - margin_left - margin_right
        content_w = max(0, available - padding_left - border_left - padding_right - border_right)
    else:
        content_w = content_width_spec

    # Box position: content area top-left
    box.x = margin_left + border_left + padding_left
    box.y = margin_top + border_top + padding_top
    box.width = content_w

    # Get font size for text layout
    font_size = styles.get('font-size', 16)
    if font_size is None:
        font_size = _get_inherited_font_size(box._element_)
        box.styles['font-size'] = font_size

    # Layout inline content for this block
    _layout_inline_v2(box, font_size, content_w)

    # Collect visible block children
    block_children = []
    for child_el in box._element_.children:
        if child_el.tag == '_text_':
            continue
        if child_el.styles.get('display') == 'none':
            continue
        block_children.append(child_el)

    if not block_children:
        box.height = 0
        return

    # Layout each child
    content_top = 0  # relative to box's content area

    for i, child_el in enumerate(block_children):
        child_box = Box(child_el.tag)
        child_box.styles = child_el.styles
        child_box._element_ = child_el

        child_margin_top = child_el.styles.get('margin-top', 0)
        child_border_top = child_el.styles.get('border-width', 0)
        child_padding_top = child_el.styles.get('padding-top', 0)
        child_margin_left = child_el.styles.get('margin-left', 0)
        child_border_left = child_el.styles.get('border-width', 0)
        child_padding_left = child_el.styles.get('padding-left', 0)

        if i == 0:
            # First child: margin edge sits at parent content top
            child_content_top = content_top + child_margin_top
        else:
            # Gap = max(prev margin-bottom, this margin-top)
            prev = block_children[i - 1]
            prev_margin_bottom = prev.styles.get('margin-bottom', 0)
            gap = max(prev_margin_bottom, child_margin_top)
            child_content_top = content_top + gap + child_margin_top

        child_box.y = box.y + child_content_top + child_border_top + child_padding_top
        child_box.x = box.x + child_margin_left + child_border_left + child_padding_left

        # Child content width = parent content width
        _layout_block_v2(child_box, content_w)

        box.children.append(child_box)
        content_top = child_content_top + child_border_top + child_padding_top + child_box.height + child_margin_bottom

    # Auto height: from content top to margin edge below last child
    last_child = block_children[-1]
    last_margin_bottom = last_child.styles.get('margin-bottom', 0)
    last_border_bottom = last_child.styles.get('border-width', 0)
    last_padding_bottom = last_child.styles.get('padding-bottom', 0)

    box.height = content_top + last_margin_bottom + last_border_bottom + last_padding_bottom


def _layout_inline_v2(box, font_size, content_w):
    """Layout inline text content for a block."""
    el = box._element_

    # Collect all text content with their font sizes
    text_spans = _collect_inline_content(el)

    if not text_spans:
        return

    # Build line boxes
    lines = []
    current_line_words = []  # list of (word_text, font_size)
    current_line_x = 0  # offset within line
    space_width = font_size // 2

    for word_text, word_font_size in text_spans:
        # Calculate word width
        word_w = _word_advance(word_text, word_font_size)

        if not current_line_words:
            # First word on line
            if current_line_x + word_w <= content_w:
                current_line_words.append((word_text, word_font_size))
                current_line_x += word_w
            else:
                # Word too wide - starts new line (rule 7)
                lines.append(_make_line(box, [], font_size, content_w))
                current_line_words = [(word_text, word_font_size)]
                current_line_x = word_w
        else:
            # Need space before word
            needed = space_width + word_w
            if current_line_x + needed <= content_w:
                current_line_words.append((word_text, word_font_size))
                current_line_x += needed
            else:
                # Start new line
                lines.append(_make_line(box, current_line_words, font_size, content_w))
                current_line_words = [(word_text, word_font_size)]
                current_line_x = word_w

    if current_line_words:
        lines.append(_make_line(box, current_line_words, font_size, content_w))

    box.lines = lines


def _collect_inline_content(el):
    """Collect inline text content as list of (word, font_size) tuples."""
    result = []

    for child in el.children:
        if child.tag == '_text_':
            text = child.text
            fs = child.styles.get('font-size', 16)
            if fs is None:
                fs = _get_inherited_font_size(child)
                child.styles['font-size'] = fs
            # Split into words
            words = text.split()
            for w in words:
                if w:
                    result.append((w, fs))
        elif child.tag == 'br':
            result.append(('<br>', el.styles.get('font-size', 16)))
        elif child.tag == 'span' or child.tag == 'b' or child.tag == 'i' or \
             child.tag in ('em', 'strong', 'code', 'a', 'small', 'big', 'sub', 'sup'):
            # Inline element - recurse
            result.extend(_collect_inline_content(child))
        # Other block elements are handled separately

    return result


def _word_advance(word, font_size):
    """Calculate width of a word based on character advances."""
    total = 0
    for ch in word:
        if ord(ch) == 0xA0:  # nbsp
            advance = font_size // 2
        else:
            advance = font_size // 2
        total += advance
    return total


def _make_line(box, words, font_size, content_w):
    """Create a line box from words."""
    if not words:
        lh = font_size + 4
        return LineBox(box.x, box.y, 0, lh, '')

    # Calculate line height (rule 8)
    max_h = 0
    for w, fs in words:
        h = fs + 4
        if h > max_h:
            max_h = h

    # Calculate line width
    line_w = 0
    first = True
    for w, fs in words:
        ww = _word_advance(w, fs)
        if not first:
            line_w += font_size // 2  # space width
        line_w += ww
        first = False

    # Join words with spaces
    text = ' '.join(w for w, _ in words)

    return LineBox(box.x, box.y, line_w, max_h, text)


def _get_inherited_font_size(el):
    """Get inherited font-size from parent."""
    parent = _parent(el)
    if parent is None:
        return 16
    fs = parent.styles.get('font-size', 16)
    if fs is None:
        return _get_inherited_font_size(parent)
    return fs


def _parent(el):
    """Find parent of an element."""
    return getattr(el, '_parent_', None)


# ---------------------------------------------------------------------------
# Output
# ---------------------------------------------------------------------------

def format_output(box):
    """Format box tree to stdout."""
    lines = []
    _format_box(box, 0, lines)
    print('\n'.join(lines))


def _format_box(box, indent_level, lines):
    if box.display == 'none':
        return

    indent = '  ' * indent_level
    lines.append(f'{indent}BLOCK {box.tag} {box.x},{box.y} {box.width}x{box.height}')

    for child in box.children:
        _format_box(child, indent_level + 1, lines)

    for line in box.lines:
        indent = '  ' * (indent_level + 1)
        lines.append(f'{indent}LINE {line.x},{line.y} {line.width}x{line.height} "{line.text}"')


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def main():
    if len(sys.argv) < 2:
        return

    filepath = sys.argv[1]
    viewport_width = 800
    if '--width' in sys.argv:
        idx = sys.argv.index('--width')
        if idx + 1 < len(sys.argv):
            viewport_width = int(sys.argv[idx + 1])

    with open(filepath, 'r', encoding='utf-8') as f:
        html_text = f.read()

    root = parse_html_v2(html_text)
    if not root.children:
        return

    # Link parent references
    _set_parents(root)

    # Apply styles
    resolve_styles(root)

    # Layout
    body_box = layout_document_v2(root, viewport_width)
    if body_box is None:
        return

    # Format output
    format_output(body_box)


def _set_parents(el, parent=None):
    """Set _parent_ references on all elements."""
    el._parent_ = parent
    for child in el.children:
        if isinstance(child, Element):
            _set_parents(child, el)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Twig: a rendering engine for a small subset of HTML and CSS."""

import re
import sys


# ---------------------------------------------------------------------------
# Rule 1 helpers
# ---------------------------------------------------------------------------

def parse_length(s):
    """Parse a length string. Returns int or None if invalid (negative)."""
    s = s.strip()
    if s.endswith('px'):
        s = s[:-2]
    try:
        v = int(s)
    except ValueError:
        return None
    if v < 0:
        return None  # Rule 2: negative is invalid
    return v


# ---------------------------------------------------------------------------
# HTML Parser
# ---------------------------------------------------------------------------

ENTITY_MAP = {
    'amp': '&', 'lt': '<', 'gt': '>', 'quot': '"',
    'apos': "'", 'nbsp': '\xa0',
}

VOID_ELEMENTS = frozenset([
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr',
])


class Element:
    __slots__ = ('tag', 'attrs', 'children', 'text')

    def __init__(self, tag, attrs=None, children=None, text=None):
        self.tag = tag
        self.attrs = attrs or {}
        self.children = children or []
        self.text = text


def decode_entities(s):
    """Decode HTML entities in text content."""
    result = []
    i = 0
    while i < len(s):
        if s[i] == '&' and i + 1 < len(s):
            if s[i + 1] == '#':
                j = i + 2
                num_str = ''
                while j < len(s) and s[j] != ';':
                    if s[j].isdigit():
                        num_str += s[j]
                    j += 1
                if j < len(s) and s[j] == ';' and num_str:
                    try:
                        code = int(num_str)
                        result.append(chr(code))
                    except (ValueError, OverflowError):
                        result.append(s[i:j + 1])
                    i = j + 1
                    continue
                else:
                    result.append(s[i])
                    i += 1
                    continue
            else:
                j = i + 1
                while j < len(s) and s[j] != ';':
                    if s[j].isalpha():
                        j += 1
                    else:
                        break
                if j < len(s) and s[j] == ';':
                    name = s[i + 1:j]
                    if name in ENTITY_MAP:
                        result.append(ENTITY_MAP[name])
                    else:
                        result.append(s[i:j + 1])
                    i = j + 1
                    continue
                else:
                    result.append(s[i])
                    i += 1
                    continue
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)


def parse_html(html_text):
    """Parse HTML into a tree of Elements."""
    # Remove comments and DOCTYPE
    html_text = re.sub(r'<!--.*?-->', '', html_text, flags=re.DOTALL)
    html_text = re.sub(r'<!DOCTYPE[^>]*>', '', html_text, flags=re.IGNORECASE)

    root = Element('root')
    pos = [0]

    def parse_open_tags():
        """Return list of open (tag, start_pos) tuples."""
        return []

    def parse_children(open_tags):
        elements = []
        while pos[0] < len(html_text):
            ch, new_pos = _parse_one_node(html_text, pos, open_tags)
            if ch is None:
                break
            if isinstance(ch, tuple) and ch[0] == '_end_':
                # Pop matching open tag
                end_tag_name = ch[1]
                found = False
                for i in range(len(open_tags) - 1, -1, -1):
                    if open_tags[i][0] == end_tag_name:
                        found = True
                        del open_tags[i:]
                        break
                continue
            elements.append(ch)
        return elements

    def _parse_one_node(text, p, open_tags):
        idx = text.find('<', p[0])
        if idx == -1:
            raw = text[p[0]:]
            return Element('_text_', text=decode_entities(text[p[0]:])), len(text)

        if idx != p[0]:
            raw = text[p[0]:idx]
            return Element('_text_', text=decode_entities(raw)), idx

        rest = text[idx + 1:]

        # End tag
        if rest.startswith('/'):
            m = re.match(r'([a-z]+)\s*>', rest, re.IGNORECASE)
            if m:
                return ('_end_', m.group(1).lower()), idx + 1 + m.end()
            return None, idx + 1

        # Skip <!...> (should already be removed but just in case)
        if rest.startswith('!'):
            end = text.find('>', idx + 1)
            if end == -1:
                return None, len(text)
            return None, end + 1

        # Start tag
        m = re.match(r'([a-z]+)(\s*)(.*)', rest, re.DOTALL | re.IGNORECASE)
        if not m:
            return None, idx + 1

        tag = m.group(1).lower()
        attrs = {}
        rest_attrs = m.group(3).rstrip('/')
        if rest_attrs.strip():
            attrs = _parse_attrs(rest_attrs)

        start_pos = idx

        if tag in VOID_ELEMENTS:
            return Element(tag, attrs=attrs), idx + 1 + len(m.group(0))

        # Check for implicit closing (<p> closes previous <p>, <li> closes previous <li>)
        if tag in ('p', 'li'):
            for i in range(len(open_tags) - 2, -1, -1):
                if open_tags[i][0] == tag:
                    close_end = open_tags[i][1]
                    children = parse_children(open_tags[i + 1:])
                    elem = Element(tag, attrs=attrs, children=children)
                    del open_tags[i + 1:]
                    return elem, close_end + len(f'</{tag}>')

        # Push onto open stack
        open_tags.append((tag, start_pos))

        # Find matching end tag
        end_tag_pos = text.find(f'</{tag}>', idx + 1)
        if end_tag_pos == -1:
            # Unclosed - take to end
            children = parse_children(open_tags)
            return Element(tag, attrs=attrs, children=children), len(text)

        children = parse_children(open_tags)
        return Element(tag, attrs=attrs, children=children), end_tag_pos + len(f'</{tag}>')

    root.children = parse_children([])
    return root


def _parse_attrs(s):
    """Parse attribute string into dict."""
    attrs = {}
    pattern = re.compile(r'''(\S+)(?:=(?:"([^"]*)"|'([^']*)'|(\S+)))?''')
    for m in pattern.finditer(s):
        name = m.group(1).lower()
        if m.group(2) is not None:
            val = m.group(2)
        elif m.group(3) is not None:
            val = m.group(3)
        elif m.group(4) is not None:
            val = m.group(4)
        else:
            val = ''
        attrs[name] = decode_entities(val)
    return attrs


# ---------------------------------------------------------------------------
# CSS Parser
# ---------------------------------------------------------------------------

def parse_css(css_text):
    """Parse CSS text into list of (selector_string, [(prop, value)]) tuples."""
    css_text = re.sub(r'/\*.*?\*/', '', css_text, flags=re.DOTALL)
    rules = []
    pattern = re.compile(r'([^{}]+)\{([^{}]*)\}')
    for m in pattern.finditer(css_text):
        selector_str = m.group(1).strip()
        decl_str = m.group(2).strip()
        declarations = _parse_declarations(decl_str)
        selectors = [s.strip() for s in selector_str.split(',')]
        for sel in selectors:
            if sel and _validate_selector(sel):
                rules.append((sel, declarations))
    return rules


def _validate_selector(sel):
    try:
        parts = sel.strip().split()
        for part in parts:
            if part == '*':
                continue
            m = re.match(r'^([a-z]*)((?:\.[a-zA-Z_][a-zA-Z0-9_-]*)*(?:#[a-zA-Z_][a-zA-Z0-9_-]*)*)$', part)
            if not m:
                return False
        return True
    except Exception:
        return False


def _parse_declarations(decl_str):
    decls = []
    parts = decl_str.split(';')
    for part in parts:
        part = part.strip()
        if not part:
            continue
        colon = part.find(':')
        if colon == -1:
            continue
        prop = part[:colon].strip().lower()
        val = part[colon + 1:].strip()
        important = False
        if val.endswith('!important'):
            val = val[:-len('!important')].strip()
            important = True
        decls.append((prop, val, important))
    return decls


def specificity(sel_str):
    sel = sel_str.strip()
    if sel == '*':
        return (0, 0, 0)
    ids = len(re.findall(r'#', sel))
    classes = len(re.findall(r'\.', sel))
    tags = len(re.findall(r'[a-z][a-z0-9]*', sel))
    return (ids, classes, tags)


# ---------------------------------------------------------------------------
# Cascade & Style Resolution
# ---------------------------------------------------------------------------

BLOCK_TAGS = frozenset([
    'body', 'div', 'p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
    'ul', 'ol', 'li', 'section', 'article', 'header', 'footer', 'main', 'blockquote',
])

KNOWN_PROPERTIES = {
    'display', 'width', 'height', 'font-size',
    'margin-top', 'margin-right', 'margin-bottom', 'margin-left',
    'padding-top', 'padding-right', 'padding-bottom', 'padding-left',
    'border-width',
}

SHORTHAND_MAP = {
    'margin': ('margin-top', 'margin-right', 'margin-bottom', 'margin-left'),
    'padding': ('padding-top', 'padding-right', 'padding-bottom', 'padding-left'),
    'border-width': ('border-width', 'border-width', 'border-width', 'border-width'),
}


def resolve_styles(root):
    """Apply styles to all elements."""
    css_rules = []
    for el in walk_elements(root):
        if el.tag == 'style':
            css_text = ''
            for child in el.children:
                if child.tag == '_text_':
                    css_text += child.text
            css_rules.extend(parse_css(css_text))

    for el in walk_elements(root):
        if el.tag == '_text_' or el.tag == 'style' or el.tag == 'script':
            continue
        _apply_styles(el, css_rules)


def walk_elements(el):
    yield el
    for child in el.children:
        if isinstance(child, Element):
            yield from walk_elements(child)


def _apply_styles(el, css_rules):
    styles = {}

    # Inline styles
    inline_decls = []
    if 'style' in el.attrs:
        inline_decls = _parse_declarations(el.attrs['style'])

    # Matching CSS rules
    matching = []
    for sel_str, decls in css_rules:
        if _matches(el, sel_str):
            spec = specificity(sel_str)
            for prop, val, important in decls:
                if prop not in KNOWN_PROPERTIES:
                    continue
                matching.append((important, spec, len(matching), prop, val))

    # Combine: inline first, then CSS
    all_candidates = []
    for prop, val, important in inline_decls:
        if prop not in KNOWN_PROPERTIES:
            continue
        parsed = _parse_value(prop, val)
        if parsed is not None:
            all_candidates.append((True, prop, parsed))

    for important, spec, order, prop, val in matching:
        parsed = _parse_value(prop, val)
        if parsed is None:
            continue
        all_candidates.append((False, prop, parsed, important, spec, order))

    # Resolve per property: last candidate wins (highest priority)
    props_seen = set()
    for c in reversed(all_candidates):
        is_inline = c[0]
        prop = c[1]
        val = c[2]
        if prop in props_seen:
            continue
        props_seen.add(prop)
        styles[prop] = val

    # Shorthand expansion
    for short, long_props in SHORTHAND_MAP.items():
        if short in styles:
            vals = styles[short]
            for lp, sp_val in zip(long_props, vals):
                styles[lp] = sp_val
            del styles[short]

    # Defaults
    if 'display' not in styles:
        styles['display'] = 'block' if el.tag in BLOCK_TAGS else 'inline'
    if 'width' not in styles:
        styles['width'] = 'auto'
    if 'height' not in styles:
        styles['height'] = 'auto'
    for side in ('top', 'right', 'bottom', 'left'):
        for prefix in ('margin-', 'padding-', 'border-'):
            key = f'{prefix}{side}'
            if key not in styles:
                styles[key] = 0
    if 'font-size' not in styles:
        styles['font-size'] = None

    el.styles = styles


def _parse_value(prop, val_str):
    val_str = val_str.strip()

    if prop == 'display':
        if val_str in ('block', 'inline', 'none'):
            return val_str
        return None

    if prop in ('width', 'height'):
        if val_str == 'auto':
            return 'auto'
        v = parse_length(val_str)
        return v

    if prop == 'font-size':
        v = parse_length(val_str)
        return v

    if prop in SHORTHAND_MAP.values():
        v = parse_length(val_str)
        return v

    return None


def _matches(el, selector_str):
    parts = selector_str.split()
    for i in range(len(parts)):
        part = parts[-(i + 1)]
        if i == 0:
            if not _matches_compound(el, part):
                return False
        else:
            parent = getattr(el, '_parent_', None)
            found = False
            while parent:
                if _matches_compound(parent, part):
                    found = True
                    break
                parent = getattr(parent, '_parent_', None)
            if not found:
                return False
    return True


def _matches_compound(el, compound):
    if compound == '*':
        return True

    m = re.match(r'^([a-z]*)((?:\.[a-zA-Z_][a-zA-Z0-9_-]*)*(?:#[a-zA-Z_][a-zA-Z0-9_-]*)*)$', compound)
    if not m:
        return False

    tag_part = m.group(1)
    class_id_part = m.group(2)

    if tag_part and el.tag != tag_part:
        return False

    if class_id_part:
        classes = re.findall(r'\.([a-zA-Z_][a-zA-Z0-9_-]*)', class_id_part)
        ids = re.findall(r'#([a-zA-Z_][a-zA-Z0-9_-]*)', class_id_part)
        for c in classes:
            if c not in el.attrs.get('class', '').split():
                return False
        for id_val in ids:
            if el.attrs.get('id') != id_val:
                return False

    return True


# ---------------------------------------------------------------------------
# Layout Engine
# ---------------------------------------------------------------------------

class Box:
    __slots__ = ('tag', 'x', 'y', 'width', 'height', 'styles', 'children', 'lines')

    def __init__(self, tag, x=0, y=0, width=0, height=0):
        self.tag = tag
        self.x = x
        self.y = y
        self.width = width
        self.height = height
        self.styles = {}
        self.children = []
        self.lines = []


class LineBox:
    __slots__ = ('x', 'y', 'width', 'height', 'text')

    def __init__(self, x, y, width, height, text=''):
        self.x = x
        self.y = y
        self.width = width
        self.height = height
        self.text = text


def layout_document(root, viewport_width=800):
    body_el = _find_body(root)
    if body_el is None:
        return None

    body_box = Box('body')
    body_box.styles = body_el.styles
    body_box._element_ = body_el

    _layout_block(body_box, viewport_width)
    return body_box


def _find_body(root):
    for el in walk_elements(root):
        if el.tag == 'body':
            return el
    return None


def _set_parents(el, parent=None):
    el._parent_ = parent
    for child in el.children:
        if isinstance(child, Element):
            _set_parents(child, el)


def _get_inherited_font_size(el):
    parent = getattr(el, '_parent_', None)
    if parent is None:
        return 16
    fs = parent.styles.get('font-size', 16)
    if fs is None:
        return _get_inherited_font_size(parent)
    return fs


def _layout_block(box, containing_width):
    styles = box.styles
    display = styles.get('display', 'block')
    if display == 'none':
        return

    margin_top = styles.get('margin-top', 0)
    margin_right = styles.get('margin-right', 0)
    margin_bottom = styles.get('margin-bottom', 0)
    margin_left = styles.get('margin-left', 0)
    padding_top = styles.get('padding-top', 0)
    padding_right = styles.get('padding-right', 0)
    padding_bottom = styles.get('padding-bottom', 0)
    padding_left = styles.get('padding-left', 0)
    border_top = styles.get('border-width', 0)
    border_right = styles.get('border-width', 0)
    border_bottom = styles.get('border-width', 0)
    border_left = styles.get('border-width', 0)

    # Content width
    cw_spec = styles.get('width', 'auto')
    if cw_spec == 'auto':
        available = containing_width - margin_left - margin_right
        content_w = max(0, available - padding_left - border_left - padding_right - border_right)
    else:
        content_w = cw_spec

    # Box position (content area top-left)
    box.x = margin_left + border_left + padding_left
    box.y = margin_top + border_top + padding_top
    box.width = content_w

    # Font size
    font_size = styles.get('font-size', 16)
    if font_size is None:
        font_size = _get_inherited_font_size(box._element_)
        box.styles['font-size'] = font_size

    # Collect visible block children
    block_children = []
    for child_el in box._element_.children:
        if child_el.tag == '_text_':
            continue
        if child_el.styles.get('display') == 'none':
            continue
        block_children.append(child_el)

    if not block_children:
        # No children - check for explicit height
        h_spec = styles.get('height', 'auto')
        if h_spec != 'auto':
            box.height = h_spec + padding_top + border_top + margin_top + padding_bottom + border_bottom + margin_bottom
        else:
            box.height = 0
        return

    # Layout each child
    content_top = 0  # relative to box's content area

    for i, child_el in enumerate(block_children):
        child_box = Box(child_el.tag)
        child_box.styles = child_el.styles
        child_box._element_ = child_el

        cm_top = child_el.styles.get('margin-top', 0)
        cb_top = child_el.styles.get('border-width', 0)
        cp_top = child_el.styles.get('padding-top', 0)
        cm_left = child_el.styles.get('margin-left', 0)
        cb_left = child_el.styles.get('border-width', 0)
        cp_left = child_el.styles.get('padding-left', 0)

        if i == 0:
            child_content_top = content_top + cm_top
        else:
            prev = block_children[i - 1]
            prev_mb = prev.styles.get('margin-bottom', 0)
            gap = max(prev_mb, cm_top)
            child_content_top = content_top + gap + cm_top

        child_box.y = box.y + child_content_top + cb_top + cp_top
        child_box.x = box.x + cm_left + cb_left + cp_left

        _layout_block(child_box, content_w)
        box.children.append(child_box)

        content_top = child_content_top + cb_top + cp_top + child_box.height + margin_bottom

    # Auto height
    last_child = block_children[-1]
    last_mb = last_child.styles.get('margin-bottom', 0)
    last_bb = last_child.styles.get('border-width', 0)
    last_pb = last_child.styles.get('padding-bottom', 0)

    box.height = content_top + last_mb + last_bb + last_pb


def _layout_inline(box, font_size, content_w):
    """Layout inline text for a block."""
    el = box._element_
    spans = _collect_spans(el)

    if not spans:
        return

    lines = []
    current_words = []
    space_width = font_size // 2
    line_x = 0

    for word_text, word_fs in spans:
        ww = _word_width(word_text, word_fs)

        if not current_words:
            if line_x + ww <= content_w:
                current_words.append((word_text, word_fs))
                line_x += ww
            else:
                # Word too wide
                lines.append(_make_line(box, [], font_size, content_w))
                current_words = [(word_text, word_fs)]
                line_x = ww
        else:
            needed = space_width + ww
            if line_x + needed <= content_w:
                current_words.append((word_text, word_fs))
                line_x += needed
            else:
                lines.append(_make_line(box, current_words, font_size, content_w))
                current_words = [(word_text, word_fs)]
                line_x = ww

    if current_words:
        lines.append(_make_line(box, current_words, font_size, content_w))

    box.lines = lines


def _collect_spans(el):
    """Collect inline text as (word, font_size) tuples, handling <br>.

    Returns list of either (word_text, font_size) or ('<br>', font_size).
    """
    result = []
    for child in el.children:
        if child.tag == '_text_':
            text = child.text
            fs = child.styles.get('font-size', 16)
            if fs is None:
                fs = _get_inherited_font_size(child)
                child.styles['font-size'] = fs
            words = text.split()
            for w in words:
                if w:
                    result.append((w, fs))
        elif child.tag == 'br':
            result.append(('<br>', el.styles.get('font-size', 16)))
        elif child.tag in ('span', 'b', 'i', 'em', 'strong', 'code', 'a', 'small', 'big', 'sub', 'sup'):
            result.extend(_collect_spans(child))
    return result


def _word_width(word, font_size):
    total = 0
    for ch in word:
        total += font_size // 2
    return total


def _make_line(box, words, font_size, content_w):
    if not words:
        lh = font_size + 4
        return LineBox(box.x, box.y, 0, lh, '')

    max_h = max(fs + 4 for _, fs in words)

    line_w = 0
    first = True
    for w, fs in words:
        ww = _word_width(w, fs)
        if not first:
            line_w += font_size // 2
        line_w += ww
        first = False

    text = ' '.join(w for w, _ in words)
    return LineBox(box.x, box.y, line_w, max_h, text)


# ---------------------------------------------------------------------------
# Output
# ---------------------------------------------------------------------------

def format_output(box):
    lines = []
    _format_box(box, 0, lines)
    print('\n'.join(lines))


def _format_box(box, indent_level, lines):
    indent = '  ' * indent_level
    lines.append(f'{indent}BLOCK {box.tag} {box.x},{box.y} {box.width}x{box.height}')

    for child in box.children:
        _format_box(child, indent_level + 1, lines)

    for line in box.lines:
        child_indent = '  ' * (indent_level + 1)
        lines.append(f'{child_indent}LINE {line.x},{line.y} {line.width}x{line.height} "{line.text}"')


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def main():
    if len(sys.argv) < 2:
        return

    filepath = sys.argv[1]
    viewport_width = 800
    if '--width' in sys.argv:
        idx = sys.argv.index('--width')
        if idx + 1 < len(sys.argv):
            viewport_width = int(sys.argv[idx + 1])

    with open(filepath, 'r', encoding='utf-8') as f:
        html_text = f.read()

    root = parse_html(html_text)
    if not root.children:
        return

    _set_parents(root)
    resolve_styles(root)

    body_box = layout_document(root, viewport_width)
    if body_box is None:
        return

    format_output(body_box)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Twig: a rendering engine for a small subset of HTML and CSS."""

import re
import sys


# ---------------------------------------------------------------------------
# Rule 1 helpers
# ---------------------------------------------------------------------------

def parse_length(s):
    """Parse a length string. Returns int or None if invalid (negative)."""
    s = s.strip()
    if s.endswith('px'):
        s = s[:-2]
    try:
        v = int(s)
    except ValueError:
        return None
    if v < 0:
        return None
    return v


# ---------------------------------------------------------------------------
# HTML Parser
# ---------------------------------------------------------------------------

ENTITY_MAP = {
    'amp': '&', 'lt': '<', 'gt': '>', 'quot': '"',
    'apos': "'", 'nbsp': '\xa0',
}

VOID_ELEMENTS = frozenset([
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr',
])


class Element:
    __slots__ = ('tag', 'attrs', 'children', 'text')

    def __init__(self, tag, attrs=None, children=None, text=None):
        self.tag = tag
        self.attrs = attrs or {}
        self.children = children or []
        self.text = text


def decode_entities(s):
    result = []
    i = 0
    while i < len(s):
        if s[i] == '&' and i + 1 < len(s):
            if s[i + 1] == '#':
                j = i + 2
                num_str = ''
                while j < len(s) and s[j] != ';':
                    if s[j].isdigit():
                        num_str += s[j]
                    j += 1
                if j < len(s) and s[j] == ';' and num_str:
                    try:
                        code = int(num_str)
                        result.append(chr(code))
                    except (ValueError, OverflowError):
                        result.append(s[i:j + 1])
                    i = j + 1
                    continue
                else:
                    result.append(s[i])
                    i += 1
                    continue
            else:
                j = i + 1
                while j < len(s) and s[j] != ';':
                    if s[j].isalpha():
                        j += 1
                    else:
                        break
                if j < len(s) and s[j] == ';':
                    name = s[i + 1:j]
                    if name in ENTITY_MAP:
                        result.append(ENTITY_MAP[name])
                    else:
                        result.append(s[i:j + 1])
                    i = j + 1
                    continue
                else:
                    result.append(s[i])
                    i += 1
                    continue
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)


def _parse_attrs(s):
    attrs = {}
    pattern = re.compile(r'''(\S+)(?:=(?:"([^"]*)"|'([^']*)'|(\S+)))?''')
    for m in pattern.finditer(s):
        name = m.group(1).lower()
        if m.group(2) is not None:
            val = m.group(2)
        elif m.group(3) is not None:
            val = m.group(3)
        elif m.group(4) is not None:
            val = m.group(4)
        else:
            val = ''
        attrs[name] = decode_entities(val)
    return attrs


def parse_html(html_text):
    html_text = re.sub(r'<!--.*?-->', '', html_text, flags=re.DOTALL)
    html_text = re.sub(r'<!DOCTYPE[^>]*>', '', html_text, flags=re.IGNORECASE)

    root = Element('root')
    pos = [0]

    def peek(text, p, n=0):
        return text[p + n] if p + n < len(text) else None

    def parse_children(p, open_tags):
        elements = []
        while p[0] < len(html_text):
            ch, new_p = _parse_one_node(html_text, p, open_tags)
            if ch is None:
                break
            if isinstance(ch, tuple) and ch[0] == '_end_':
                end_tag_name = ch[1]
                found = False
                for i in range(len(open_tags) - 1, -1, -1):
                    if open_tags[i][0] == end_tag_name:
                        found = True
                        del open_tags[i:]
                        break
                continue
            elements.append(ch)
        return elements

    def _parse_one_node(text, p, open_tags):
        idx = text.find('<', p[0])
        if idx == -1:
            raw = text[p[0]:]
            return Element('_text_', text=decode_entities(text[p[0]:])), len(text)

        if idx != p[0]:
            raw = text[p[0]:idx]
            return Element('_text_', text=decode_entities(raw)), idx

        rest = text[idx + 1:]

        # End tag
        if rest.startswith('/'):
            m = re.match(r'([a-z]+)\s*>', rest, re.IGNORECASE)
            if m:
                return ('_end_', m.group(1).lower()), idx + 1 + m.end()
            return None, idx + 1

        # Skip <!...>
        if rest.startswith('!'):
            end = text.find('>', idx + 1)
            if end == -1:
                return None, len(text)
            return None, end + 1

        # Start tag
        m = re.match(r'([a-z]+)(\s*)(.*)', rest, re.DOTALL | re.IGNORECASE)
        if not m:
            return None, idx + 1

        tag = m.group(1).lower()
        attrs = {}
        rest_attrs = m.group(3).rstrip('/')
        if rest_attrs.strip():
            attrs = _parse_attrs(rest_attrs)

        start_pos = idx
        consumed = idx + 1 + len(m.group(0))

        if tag in VOID_ELEMENTS:
            return Element(tag, attrs=attrs), consumed

        # Check for implicit closing (<p> closes previous <p>, <li> closes previous <li>)
        if tag in ('p', 'li'):
            for i in range(len(open_tags) - 2, -1, -1):
                if open_tags[i][0] == tag:
                    close_end = open_tags[i][1]
                    children = parse_children([close_end], open_tags[i + 1:])
                    elem = Element(tag, attrs=attrs, children=children)
                    del open_tags[i + 1:]
                    return elem, close_end + len(f'</{tag}>')

        open_tags.append((tag, start_pos))

        end_tag_pos = text.find(f'</{tag}>', consumed)
        if end_tag_pos == -1:
            children = parse_children([len(text)], open_tags)
            return Element(tag, attrs=attrs, children=children), len(text)

        children = parse_children([end_tag_pos], open_tags)
        return Element(tag, attrs=attrs, children=children), end_tag_pos + len(f'</{tag}>')

    root.children = parse_children([0], [])
    return root


# ---------------------------------------------------------------------------
# CSS Parser
# ---------------------------------------------------------------------------

def parse_css(css_text):
    css_text = re.sub(r'/\*.*?\*/', '', css_text, flags=re.DOTALL)
    rules = []
    pattern = re.compile(r'([^{}]+)\{([^{}]*)\}')
    for m in pattern.finditer(css_text):
        selector_str = m.group(1).strip()
        decl_str = m.group(2).strip()
        declarations = _parse_declarations(decl_str)
        selectors = [s.strip() for s in selector_str.split(',')]
        for sel in selectors:
            if sel and _validate_selector(sel):
                rules.append((sel, declarations))
    return rules


def _validate_selector(sel):
    try:
        parts = sel.strip().split()
        for part in parts:
            if part == '*':
                continue
            m = re.match(r'^([a-z]*)((?:\.[a-zA-Z_][a-zA-Z0-9_-]*)*(?:#[a-zA-Z_][a-zA-Z0-9_-]*)*)$', part)
            if not m:
                return False
        return True
    except Exception:
        return False


def _parse_declarations(decl_str):
    decls = []
    parts = decl_str.split(';')
    for part in parts:
        part = part.strip()
        if not part:
            continue
        colon = part.find(':')
        if colon == -1:
            continue
        prop = part[:colon].strip().lower()
        val = part[colon + 1:].strip()
        important = False
        if val.endswith('!important'):
            val = val[:-len('!important')].strip()
            important = True
        decls.append((prop, val, important))
    return decls


def specificity(sel_str):
    sel = sel_str.strip()
    if sel == '*':
        return (0, 0, 0)
    ids = len(re.findall(r'#', sel))
    classes = len(re.findall(r'\.', sel))
    tags = len(re.findall(r'[a-z][a-z0-9]*', sel))
    return (ids, classes, tags)


# ---------------------------------------------------------------------------
# Cascade & Style Resolution
# ---------------------------------------------------------------------------

BLOCK_TAGS = frozenset([
    'body', 'div', 'p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
    'ul', 'ol', 'li', 'section', 'article', 'header', 'footer', 'main', 'blockquote',
])

KNOWN_PROPERTIES = {
    'display', 'width', 'height', 'font-size',
    'margin-top', 'margin-right', 'margin-bottom', 'margin-left',
    'padding-top', 'padding-right', 'padding-bottom', 'padding-left',
    'border-width',
}

SHORTHAND_MAP = {
    'margin': ('margin-top', 'margin-right', 'margin-bottom', 'margin-left'),
    'padding': ('padding-top', 'padding-right', 'padding-bottom', 'padding-left'),
    'border-width': ('border-width', 'border-width', 'border-width', 'border-width'),
}


def resolve_styles(root):
    css_rules = []
    for el in walk_elements(root):
        if el.tag == 'style':
            css_text = ''
            for child in el.children:
                if child.tag == '_text_':
                    css_text += child.text
            css_rules.extend(parse_css(css_text))

    for el in walk_elements(root):
        if el.tag == '_text_' or el.tag == 'style' or el.tag == 'script':
            continue
        _apply_styles(el, css_rules)


def walk_elements(el):
    yield el
    for child in el.children:
        if isinstance(child, Element):
            yield from walk_elements(child)


def _apply_styles(el, css_rules):
    styles = {}

    inline_decls = []
    if 'style' in el.attrs:
        inline_decls = _parse_declarations(el.attrs['style'])

    matching = []
    for sel_str, decls in css_rules:
        if _matches(el, sel_str):
            spec = specificity(sel_str)
            for prop, val, important in decls:
                if prop not in KNOWN_PROPERTIES:
                    continue
                matching.append((important, spec, len(matching), prop, val))

    all_candidates = []
    for prop, val, important in inline_decls:
        if prop not in KNOWN_PROPERTIES:
            continue
        parsed = _parse_value(prop, val)
        if parsed is not None:
            all_candidates.append((True, prop, parsed))

    for important, spec, order, prop, val in matching:
        parsed = _parse_value(prop, val)
        if parsed is None:
            continue
        all_candidates.append((False, prop, parsed, important, spec, order))

    props_seen = set()
    for c in reversed(all_candidates):
        prop = c[1]
        val = c[2]
        if prop in props_seen:
            continue
        props_seen.add(prop)
        styles[prop] = val

    for short, long_props in SHORTHAND_MAP.items():
        if short in styles:
            vals = styles[short]
            for lp, sp_val in zip(long_props, vals):
                styles[lp] = sp_val
            del styles[short]

    if 'display' not in styles:
        styles['display'] = 'block' if el.tag in BLOCK_TAGS else 'inline'
    if 'width' not in styles:
        styles['width'] = 'auto'
    if 'height' not in styles:
        styles['height'] = 'auto'
    for side in ('top', 'right', 'bottom', 'left'):
        for prefix in ('margin-', 'padding-', 'border-'):
            key = f'{prefix}{side}'
            if key not in styles:
                styles[key] = 0
    if 'font-size' not in styles:
        styles['font-size'] = None

    el.styles = styles


def _parse_value(prop, val_str):
    val_str = val_str.strip()

    if prop == 'display':
        if val_str in ('block', 'inline', 'none'):
            return val_str
        return None

    if prop in ('width', 'height'):
        if val_str == 'auto':
            return 'auto'
        v = parse_length(val_str)
        return v

    if prop == 'font-size':
        v = parse_length(val_str)
        return v

    if prop in SHORTHAND_MAP.values():
        v = parse_length(val_str)
        return v

    return None


def _matches(el, selector_str):
    parts = selector_str.split()
    for i in range(len(parts)):
        part = parts[-(i + 1)]
        if i == 0:
            if not _matches_compound(el, part):
                return False
        else:
            parent = getattr(el, '_parent_', None)
            found = False
            while parent:
                if _matches_compound(parent, part):
                    found = True
                    break
                parent = getattr(parent, '_parent_', None)
            if not found:
                return False
    return True


def _matches_compound(el, compound):
    if compound == '*':
        return True

    m = re.match(r'^([a-z]*)((?:\.[a-zA-Z_][a-zA-Z0-9_-]*)*(?:#[a-zA-Z_][a-zA-Z0-9_-]*)*)$', compound)
    if not m:
        return False

    tag_part = m.group(1)
    class_id_part = m.group(2)

    if tag_part and el.tag != tag_part:
        return False

    if class_id_part:
        classes = re.findall(r'\.([a-zA-Z_][a-zA-Z0-9_-]*)', class_id_part)
        ids = re.findall(r'#([a-zA-Z_][a-zA-Z0-9_-]*)', class_id_part)
        for c in classes:
            if c not in el.attrs.get('class', '').split():
                return False
        for id_val in ids:
            if el.attrs.get('id') != id_val:
                return False

    return True


# ---------------------------------------------------------------------------
# Layout Engine
# ---------------------------------------------------------------------------

class Box:
    __slots__ = ('tag', 'x', 'y', 'width', 'height', 'styles', 'children', 'lines')

    def __init__(self, tag, x=0, y=0, width=0, height=0):
        self.tag = tag
        self.x = x
        self.y = y
        self.width = width
        self.height = height
        self.styles = {}
        self.children = []
        self.lines = []


class LineBox:
    __slots__ = ('x', 'y', 'width', 'height', 'text')

    def __init__(self, x, y, width, height, text=''):
        self.x = x
        self.y = y
        self.width = width
        self.height = height
        self.text = text


def layout_document(root, viewport_width=800):
    body_el = _find_body(root)
    if body_el is None:
        return None

    body_box = Box('body')
    body_box.styles = body_el.styles
    body_box._element_ = body_el

    _layout_block(body_box, viewport_width)
    return body_box


def _find_body(root):
    for el in walk_elements(root):
        if el.tag == 'body':
            return el
    return None


def _set_parents(el, parent=None):
    el._parent_ = parent
    for child in el.children:
        if isinstance(child, Element):
            _set_parents(child, el)


def _get_inherited_font_size(el):
    parent = getattr(el, '_parent_', None)
    if parent is None:
        return 16
    fs = parent.styles.get('font-size', 16)
    if fs is None:
        return _get_inherited_font_size(parent)
    return fs


def _layout_block(box, containing_width):
    styles = box.styles
    display = styles.get('display', 'block')
    if display == 'none':
        return

    margin_top = styles.get('margin-top', 0)
    margin_right = styles.get('margin-right', 0)
    margin_bottom = styles.get('margin-bottom', 0)
    margin_left = styles.get('margin-left', 0)
    padding_top = styles.get('padding-top', 0)
    padding_right = styles.get('padding-right', 0)
    padding_bottom = styles.get('padding-bottom', 0)
    padding_left = styles.get('padding-left', 0)
    border_top = styles.get('border-width', 0)
    border_right = styles.get('border-width', 0)
    border_bottom = styles.get('border-width', 0)
    border_left = styles.get('border-width', 0)

    cw_spec = styles.get('width', 'auto')
    if cw_spec == 'auto':
        available = containing_width - margin_left - margin_right
        content_w = max(0, available - padding_left - border_left - padding_right - border_right)
    else:
        content_w = cw_spec

    box.x = margin_left + border_left + padding_left
    box.y = margin_top + border_top + padding_top
    box.width = content_w

    font_size = styles.get('font-size', 16)
    if font_size is None:
        font_size = _get_inherited_font_size(box._element_)
        box.styles['font-size'] = font_size

    block_children = []
    for child_el in box._element_.children:
        if child_el.tag == '_text_':
            continue
        if child_el.styles.get('display') == 'none':
            continue
        block_children.append(child_el)

    if not block_children:
        h_spec = styles.get('height', 'auto')
        if h_spec != 'auto':
            box.height = h_spec + padding_top + border_top + margin_top + padding_bottom + border_bottom + margin_bottom
        else:
            box.height = 0
        return

    content_top = 0

    for i, child_el in enumerate(block_children):
        child_box = Box(child_el.tag)
        child_box.styles = child_el.styles.copy()
        child_box._element_ = child_el

        cm_top = child_el.styles.get('margin-top', 0)
        cb_top = child_el.styles.get('border-width', 0)
        cp_top = child_el.styles.get('padding-top', 0)
        cm_left = child_el.styles.get('margin-left', 0)
        cb_left = child_el.styles.get('border-width', 0)
        cp_left = child_el.styles.get('padding-left', 0)

        if i == 0:
            child_content_top = content_top + cm_top
        else:
            prev = block_children[i - 1]
            prev_mb = prev.styles.get('margin-bottom', 0)
            gap = max(prev_mb, cm_top)
            child_content_top = content_top + gap + cm_top

        child_box.y = box.y + child_content_top + cb_top + cp_left  # fix: should be cp_top
        child_box.x = box.x + cm_left + cb_left + cp_left

        _layout_block(child_box, content_w)
        box.children.append(child_box)

        content_top = child_content_top + cb_top + cp_top + child_box.height + margin_bottom

    last_child = block_children[-1]
    last_mb = last_child.styles.get('margin-bottom', 0)
    last_bb = last_child.styles.get('border-width', 0)
    last_pb = last_child.styles.get('padding-bottom', 0)

    box.height = content_top + last_mb + last_bb + last_pb


def _layout_inline(box, font_size, content_w):
    el = box._element_
    spans = _collect_spans(el)

    if not spans:
        return

    lines = []
    current_words = []
    space_width = font_size // 2
    line_x = 0

    for word_text, word_fs in spans:
        ww = _word_width(word_text, word_fs)

        if not current_words:
            if line_x + ww <= content_w:
                current_words.append((word_text, word_fs))
                line_x += ww
            else:
                lines.append(_make_line(box, [], font_size, content_w))
                current_words = [(word_text, word_fs)]
                line_x = ww
        else:
            needed = space_width + ww
            if line_x + needed <= content_w:
                current_words.append((word_text, word_fs))
                line_x += needed
            else:
                lines.append(_make_line(box, current_words, font_size, content_w))
                current_words = [(word_text, word_fs)]
                line_x = ww

    if current_words:
        lines.append(_make_line(box, current_words, font_size, content_w))

    box.lines = lines


def _collect_spans(el):
    result = []
    for child in el.children:
        if child.tag == '_text_':
            text = child.text
            fs = child.styles.get('font-size', 16)
            if fs is None:
                fs = _get_inherited_font_size(child)
                child.styles['font-size'] = fs
            words = text.split()
            for w in words:
                if w:
                    result.append((w, fs))
        elif child.tag == 'br':
            result.append(('<br>', el.styles.get('font-size', 16)))
        elif child.tag in ('span', 'b', 'i', 'em', 'strong', 'code', 'a', 'small', 'big', 'sub', 'sup'):
            result.extend(_collect_spans(child))
    return result


def _word_width(word, font_size):
    total = 0
    for ch in word:
        total += font_size // 2
    return total


def _make_line(box, words, font_size, content_w):
    if not words:
        lh = font_size + 4
        return LineBox(box.x, box.y, 0, lh, '')

    max_h = max(fs + 4 for _, fs in words)

    line_w = 0
    first = True
    for w, fs in words:
        ww = _word_width(w, fs)
        if not first:
            line_w += font_size // 2
        line_w += ww
        first = False

    text = ' '.join(w for w, _ in words)
    return LineBox(box.x, box.y, line_w, max_h, text)


# ---------------------------------------------------------------------------
# Output
# ---------------------------------------------------------------------------

def format_output(box):
    lines = []
    _format_box(box, 0, lines)
    print('\n'.join(lines))


def _format_box(box, indent_level, lines):
    indent = '  ' * indent_level
    lines.append(f'{indent}BLOCK {box.tag} {box.x},{box.y} {box.width}x{box.height}')

    for child in box.children:
        _format_box(child, indent_level + 1, lines)

    for line in box.lines:
        child_indent = '  ' * (indent_level + 1)
        lines.append(f'{child_indent}LINE {line.x},{line.y} {line.width}x{line.height} "{line.text}"')


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def main():
    if len(sys.argv) < 2:
        return

    filepath = sys.argv[1]
    viewport_width = 800
    if '--width' in sys.argv:
        idx = sys.argv.index('--width')
        if idx + 1 < len(sys.argv):
            viewport_width = int(sys.argv[idx + 1])

    with open(filepath, 'r', encoding='utf-8') as f:
        html_text = f.read()

    root = parse_html(html_text)
    if not root.children:
        return

    _set_parents(root)
    resolve_styles(root)

    body_box = layout_document(root, viewport_width)
    if body_box is None:
        return

    format_output(body_box)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Twig: a rendering engine for a small subset of HTML and CSS."""

import re
import sys


def parse_length(s):
    s = s.strip()
    if s.endswith('px'):
        s = s[:-2]
    try:
        v = int(s)
    except ValueError:
        return None
    if v < 0:
        return None
    return v


ENTITY_MAP = {
    'amp': '&', 'lt': '<', 'gt': '>', 'quot': '"',
    'apos': "'", 'nbsp': '\xa0',
}

VOID_ELEMENTS = frozenset([
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr',
])


class Element:
    __slots__ = ('tag', 'attrs', 'children', 'text')

    def __init__(self, tag, attrs=None, children=None, text=None):
        self.tag = tag
        self.attrs = attrs or {}
        self.children = children or []
        self.text = text


def decode_entities(s):
    result = []
    i = 0
    while i < len(s):
        if s[i] == '&' and i + 1 < len(s):
            if s[i + 1] == '#':
                j = i + 2
                num_str = ''
                while j < len(s) and s[j] != ';':
                    if s[j].isdigit():
                        num_str += s[j]
                    j += 1
                if j < len(s) and s[j] == ';' and num_str:
                    try:
                        code = int(num_str)
                        result.append(chr(code))
                    except (ValueError, OverflowError):
                        result.append(s[i:j + 1])
                    i = j + 1
                    continue
                else:
                    result.append(s[i])
                    i += 1
                    continue
            else:
                j = i + 1
                while j < len(s) and s[j] != ';':
                    if s[j].isalpha():
                        j += 1
                    else:
                        break
                if j < len(s) and s[j] == ';':
                    name = s[i + 1:j]
                    if name in ENTITY_MAP:
                        result.append(ENTITY_MAP[name])
                    else:
                        result.append(s[i:j + 1])
                    i = j + 1
                    continue
                else:
                    result.append(s[i])
                    i += 1
                    continue
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)


def _parse_attrs(s):
    attrs = {}
    pattern = re.compile(r'''(\S+)(?:=(?:"([^"]*)"|'([^']*)'|(\S+)))?''')
    for m in pattern.finditer(s):
        name = m.group(1).lower()
        if m.group(2) is not None:
            val = m.group(2)
        elif m.group(3) is not None:
            val = m.group(3)
        elif m.group(4) is not None:
            val = m.group(4)
        else:
            val = ''
        attrs[name] = decode_entities(val)
    return attrs


# Global mutable state for parser
HTML_TEXT = ''


def parse_html(html_text):
    global HTML_TEXT
    HTML_TEXT = html_text
    HTML_TEXT = re.sub(r'<!--.*?-->', '', HTML_TEXT, flags=re.DOTALL)
    HTML_TEXT = re.sub(r'<!DOCTYPE[^>]*>', '', HTML_TEXT, flags=re.IGNORECASE)

    root = Element('root')
    root.children = _parse_children(0, len(HTML_TEXT), [])
    return root


def _parse_children(start, end, open_tags):
    elements = []
    p = start
    while p < end:
        ch, new_p = _parse_one_node(p, open_tags)
        if ch is None:
            break
        if isinstance(ch, tuple) and ch[0] == '_end_':
            end_tag_name = ch[1]
            found = False
            for i in range(len(open_tags) - 1, -1, -1):
                if open_tags[i][0] == end_tag_name:
                    found = True
                    del open_tags[i:]
                    break
            continue
        elements.append(ch)
    return elements


def _parse_one_node(p, open_tags):
    idx = HTML_TEXT.find('<', p)
    if idx == -1 or idx >= len(HTML_TEXT):
        raw = HTML_TEXT[p:]
        return Element('_text_', text=decode_entities(HTML_TEXT[p:])), len(HTML_TEXT)

    if idx != p:
        raw = HTML_TEXT[p:idx]
        return Element('_text_', text=decode_entities(raw)), idx

    rest = HTML_TEXT[idx + 1:]

    # End tag
    if rest.startswith('/'):
        m = re.match(r'([a-z]+)\s*>', rest, re.IGNORECASE)
        if m:
            return ('_end_', m.group(1).lower()), idx + 1 + m.end()
        return None, idx + 1

    # Skip <!...>
    if rest.startswith('!'):
        end = HTML_TEXT.find('>', idx + 1)
        if end == -1:
            return None, len(HTML_TEXT)
        return None, end + 1

    # Start tag
    m = re.match(r'([a-z]+)(\s*)(.*)', rest, re.DOTALL | re.IGNORECASE)
    if not m:
        return None, idx + 1

    tag = m.group(1).lower()
    attrs = {}
    rest_attrs = m.group(3).rstrip('/')
    if rest_attrs.strip():
        attrs = _parse_attrs(rest_attrs)

    start_pos = idx
    consumed = idx + 1 + len(m.group(0))

    if tag in VOID_ELEMENTS:
        return Element(tag, attrs=attrs), consumed

    # Check for implicit closing
    if tag in ('p', 'li'):
        for i in range(len(open_tags) - 2, -1, -1):
            if open_tags[i][0] == tag:
                close_end = open_tags[i][1]
                children = _parse_children(consumed, close_end, open_tags[i + 1:])
                elem = Element(tag, attrs=attrs, children=children)
                del open_tags[i + 1:]
                return elem, close_end + len(f'</{tag}>')

    open_tags.append((tag, start_pos))

    end_tag_pos = HTML_TEXT.find(f'</{tag}>', consumed)
    if end_tag_pos == -1:
        children = _parse_children(consumed, len(HTML_TEXT), open_tags)
        return Element(tag, attrs=attrs, children=children), len(HTML_TEXT)

    children = _parse_children(consumed, end_tag_pos, open_tags)
    return Element(tag, attrs=attrs, children=children), end_tag_pos + len(f'</{tag}>')


# ---------------------------------------------------------------------------
# CSS Parser
# ---------------------------------------------------------------------------

def parse_css(css_text):
    css_text = re.sub(r'/\*.*?\*/', '', css_text, flags=re.DOTALL)
    rules = []
    pattern = re.compile(r'([^{}]+)\{([^{}]*)\}')
    for m in pattern.finditer(css_text):
        selector_str = m.group(1).strip()
        decl_str = m.group(2).strip()
        declarations = _parse_declarations(decl_str)
        selectors = [s.strip() for s in selector_str.split(',')]
        for sel in selectors:
            if sel and _validate_selector(sel):
                rules.append((sel, declarations))
    return rules


def _validate_selector(sel):
    try:
        parts = sel.strip().split()
        for part in parts:
            if part == '*':
                continue
            m = re.match(r'^([a-z]*)((?:\.[a-zA-Z_][a-zA-Z0-9_-]*)*(?:#[a-zA-Z_][a-zA-Z0-9_-]*)*)$', part)
            if not m:
                return False
        return True
    except Exception:
        return False


def _parse_declarations(decl_str):
    decls = []
    parts = decl_str.split(';')
    for part in parts:
        part = part.strip()
        if not part:
            continue
        colon = part.find(':')
        if colon == -1:
            continue
        prop = part[:colon].strip().lower()
        val = part[colon + 1:].strip()
        important = False
        if val.endswith('!important'):
            val = val[:-len('!important')].strip()
            important = True
        decls.append((prop, val, important))
    return decls


def specificity(sel_str):
    sel = sel_str.strip()
    if sel == '*':
        return (0, 0, 0)
    ids = len(re.findall(r'#', sel))
    classes = len(re.findall(r'\.', sel))
    tags = len(re.findall(r'[a-z][a-z0-9]*', sel))
    return (ids, classes, tags)


# ---------------------------------------------------------------------------
# Cascade & Style Resolution
# ---------------------------------------------------------------------------

BLOCK_TAGS = frozenset([
    'body', 'div', 'p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
    'ul', 'ol', 'li', 'section', 'article', 'header', 'footer', 'main', 'blockquote',
])

KNOWN_PROPERTIES = {
    'display', 'width', 'height', 'font-size',
    'margin-top', 'margin-right', 'margin-bottom', 'margin-left',
    'padding-top', 'padding-right', 'padding-bottom', 'padding-left',
    'border-width',
}

SHORTHAND_MAP = {
    'margin': ('margin-top', 'margin-right', 'margin-bottom', 'margin-left'),
    'padding': ('padding-top', 'padding-right', 'padding-bottom', 'padding-left'),
    'border-width': ('border-width', 'border-width', 'border-width', 'border-width'),
}


def resolve_styles(root):
    css_rules = []
    for el in walk_elements(root):
        if el.tag == 'style':
            css_text = ''
            for child in el.children:
                if child.tag == '_text_':
                    css_text += child.text
            css_rules.extend(parse_css(css_text))

    for el in walk_elements(root):
        if el.tag == '_text_' or el.tag == 'style' or el.tag == 'script':
            continue
        _apply_styles(el, css_rules)


def walk_elements(el):
    yield el
    for child in el.children:
        if isinstance(child, Element):
            yield from walk_elements(child)


def _apply_styles(el, css_rules):
    styles = {}

    inline_decls = []
    if 'style' in el.attrs:
        inline_decls = _parse_declarations(el.attrs['style'])

    matching = []
    for sel_str, decls in css_rules:
        if _matches(el, sel_str):
            spec = specificity(sel_str)
            for prop, val, important in decls:
                if prop not in KNOWN_PROPERTIES:
                    continue
                matching.append((important, spec, len(matching), prop, val))

    all_candidates = []
    for prop, val, important in inline_decls:
        if prop not in KNOWN_PROPERTIES:
            continue
        parsed = _parse_value(prop, val)
        if parsed is not None:
            all_candidates.append((True, prop, parsed))

    for important, spec, order, prop, val in matching:
        parsed = _parse_value(prop, val)
        if parsed is None:
            continue
        all_candidates.append((False, prop, parsed, important, spec, order))

    props_seen = set()
    for c in reversed(all_candidates):
        prop = c[1]
        val = c[2]
        if prop in props_seen:
            continue
        props_seen.add(prop)
        styles[prop] = val

    for short, long_props in SHORTHAND_MAP.items():
        if short in styles:
            vals = styles[short]
            for lp, sp_val in zip(long_props, vals):
                styles[lp] = sp_val
            del styles[short]

    if 'display' not in styles:
        styles['display'] = 'block' if el.tag in BLOCK_TAGS else 'inline'
    if 'width' not in styles:
        styles['width'] = 'auto'
    if 'height' not in styles:
        styles['height'] = 'auto'
    for side in ('top', 'right', 'bottom', 'left'):
        for prefix in ('margin-', 'padding-', 'border-'):
            key = f'{prefix}{side}'
            if key not in styles:
                styles[key] = 0
    if 'font-size' not in styles:
        styles['font-size'] = None

    el.styles = styles


def _parse_value(prop, val_str):
    val_str = val_str.strip()

    if prop == 'display':
        if val_str in ('block', 'inline', 'none'):
            return val_str
        return None

    if prop in ('width', 'height'):
        if val_str == 'auto':
            return 'auto'
        v = parse_length(val_str)
        return v

    if prop == 'font-size':
        v = parse_length(val_str)
        return v

    if prop in SHORTHAND_MAP.values():
        v = parse_length(val_str)
        return v

    return None


def _matches(el, selector_str):
    parts = selector_str.split()
    for i in range(len(parts)):
        part = parts[-(i + 1)]
        if i == 0:
            if not _matches_compound(el, part):
                return False
        else:
            parent = getattr(el, '_parent_', None)
            found = False
            while parent:
                if _matches_compound(parent, part):
                    found = True
                    break
                parent = getattr(parent, '_parent_', None)
            if not found:
                return False
    return True


def _matches_compound(el, compound):
    if compound == '*':
        return True

    m = re.match(r'^([a-z]*)((?:\.[a-zA-Z_][a-zA-Z0-9_-]*)*(?:#[a-zA-Z_][a-zA-Z0-9_-]*)*)$', compound)
    if not m:
        return False

    tag_part = m.group(1)
    class_id_part = m.group(2)

    if tag_part and el.tag != tag_part:
        return False

    if class_id_part:
        classes = re.findall(r'\.([a-zA-Z_][a-zA-Z0-9_-]*)', class_id_part)
        ids = re.findall(r'#([a-zA-Z_][a-zA-Z0-9_-]*)', class_id_part)
        for c in classes:
            if c not in el.attrs.get('class', '').split():
                return False
        for id_val in ids:
            if el.attrs.get('id') != id_val:
                return False

    return True


# ---------------------------------------------------------------------------
# Layout Engine
# ---------------------------------------------------------------------------

class Box:
    __slots__ = ('tag', 'x', 'y', 'width', 'height', 'styles', 'children', 'lines')

    def __init__(self, tag, x=0, y=0, width=0, height=0):
        self.tag = tag
        self.x = x
        self.y = y
        self.width = width
        self.height = height
        self.styles = {}
        self.children = []
        self.lines = []


class LineBox:
    __slots__ = ('x', 'y', 'width', 'height', 'text')

    def __init__(self, x, y, width, height, text=''):
        self.x = x
        self.y = y
        self.width = width
        self.height = height
        self.text = text


def layout_document(root, viewport_width=800):
    body_el = _find_body(root)
    if body_el is None:
        return None

    body_box = Box('body')
    body_box.styles = body_el.styles
    body_box._element_ = body_el

    _layout_block(body_box, viewport_width)
    return body_box


def _find_body(root):
    for el in walk_elements(root):
        if el.tag == 'body':
            return el
    return None


def _set_parents(el, parent=None):
    el._parent_ = parent
    for child in el.children:
        if isinstance(child, Element):
            _set_parents(child, el)


def _get_inherited_font_size(el):
    parent = getattr(el, '_parent_', None)
    if parent is None:
        return 16
    fs = parent.styles.get('font-size', 16)
    if fs is None:
        return _get_inherited_font_size(parent)
    return fs


def _layout_block(box, containing_width):
    styles = box.styles
    display = styles.get('display', 'block')
    if display == 'none':
        return

    margin_top = styles.get('margin-top', 0)
    margin_right = styles.get('margin-right', 0)
    margin_bottom = styles.get('margin-bottom', 0)
    margin_left = styles.get('margin-left', 0)
    padding_top = styles.get('padding-top', 0)
    padding_right = styles.get('padding-right', 0)
    padding_bottom = styles.get('padding-bottom', 0)
    padding_left = styles.get('padding-left', 0)
    border_top = styles.get('border-width', 0)
    border_right = styles.get('border-width', 0)
    border_bottom = styles.get('border-width', 0)
    border_left = styles.get('border-width', 0)

    cw_spec = styles.get('width', 'auto')
    if cw_spec == 'auto':
        available = containing_width - margin_left - margin_right
        content_w = max(0, available - padding_left - border_left - padding_right - border_right)
    else:
        content_w = cw_spec

    box.x = margin_left + border_left + padding_left
    box.y = margin_top + border_top + padding_top
    box.width = content_w

    font_size = styles.get('font-size', 16)
    if font_size is None:
        font_size = _get_inherited_font_size(box._element_)
        box.styles['font-size'] = font_size

    block_children = []
    for child_el in box._element_.children:
        if child_el.tag == '_text_':
            continue
        if child_el.styles.get('display') == 'none':
            continue
        block_children.append(child_el)

    if not block_children:
        h_spec = styles.get('height', 'auto')
        if h_spec != 'auto':
            box.height = h_spec + padding_top + border_top + margin_top + padding_bottom + border_bottom + margin_bottom
        else:
            box.height = 0
        return

    content_top = 0

    for i, child_el in enumerate(block_children):
        child_box = Box(child_el.tag)
        child_box.styles = child_el.styles.copy()
        child_box._element_ = child_el

        cm_top = child_el.styles.get('margin-top', 0)
        cb_top = child_el.styles.get('border-width', 0)
        cp_top = child_el.styles.get('padding-top', 0)
        cm_left = child_el.styles.get('margin-left', 0)
        cb_left = child_el.styles.get('border-width', 0)
        cp_left = child_el.styles.get('padding-left', 0)

        if i == 0:
            child_content_top = content_top + cm_top
        else:
            prev = block_children[i - 1]
            prev_mb = prev.styles.get('margin-bottom', 0)
            gap = max(prev_mb, cm_top)
            child_content_top = content_top + gap + cm_top

        child_box.y = box.y + child_content_top + cb_top + cp_top
        child_box.x = box.x + cm_left + cb_left + cp_left

        _layout_block(child_box, content_w)
        box.children.append(child_box)

        content_top = child_content_top + cb_top + cp_top + child_box.height + margin_bottom

    last_child = block_children[-1]
    last_mb = last_child.styles.get('margin-bottom', 0)
    last_bb = last_child.styles.get('border-width', 0)
    last_pb = last_child.styles.get('padding-bottom', 0)

    box.height = content_top + last_mb + last_bb + last_pb


def _layout_inline(box, font_size, content_w):
    el = box._element_
    spans = _collect_spans(el)

    if not spans:
        return

    lines = []
    current_words = []
    space_width = font_size // 2
    line_x = 0

    for word_text, word_fs in spans:
        ww = _word_width(word_text, word_fs)

        if not current_words:
            if line_x + ww <= content_w:
                current_words.append((word_text, word_fs))
                line_x += ww
            else:
                lines.append(_make_line(box, [], font_size, content_w))
                current_words = [(word_text, word_fs)]
                line_x = ww
        else:
            needed = space_width + ww
            if line_x + needed <= content_w:
                current_words.append((word_text, word_fs))
                line_x += needed
            else:
                lines.append(_make_line(box, current_words, font_size, content_w))
                current_words = [(word_text, word_fs)]
                line_x = ww

    if current_words:
        lines.append(_make_line(box, current_words, font_size, content_w))

    box.lines = lines


def _collect_spans(el):
    result = []
    for child in el.children:
        if child.tag == '_text_':
            text = child.text
            fs = child.styles.get('font-size', 16)
            if fs is None:
                fs = _get_inherited_font_size(child)
                child.styles['font-size'] = fs
            words = text.split()
            for w in words:
                if w:
                    result.append((w, fs))
        elif child.tag == 'br':
            result.append(('<br>', el.styles.get('font-size', 16)))
        elif child.tag in ('span', 'b', 'i', 'em', 'strong', 'code', 'a', 'small', 'big', 'sub', 'sup'):
            result.extend(_collect_spans(child))
    return result


def _word_width(word, font_size):
    total = 0
    for ch in word:
        total += font_size // 2
    return total


def _make_line(box, words, font_size, content_w):
    if not words:
        lh = font_size + 4
        return LineBox(box.x, box.y, 0, lh, '')

    max_h = max(fs + 4 for _, fs in words)

    line_w = 0
    first = True
    for w, fs in words:
        ww = _word_width(w, fs)
        if not first:
            line_w += font_size // 2
        line_w += ww
        first = False

    text = ' '.join(w for w, _ in words)
    return LineBox(box.x, box.y, line_w, max_h, text)


# ---------------------------------------------------------------------------
# Output
# ---------------------------------------------------------------------------

def format_output(box):
    lines = []
    _format_box(box, 0, lines)
    print('\n'.join(lines))


def _format_box(box, indent_level, lines):
    indent = '  ' * indent_level
    lines.append(f'{indent}BLOCK {box.tag} {box.x},{box.y} {box.width}x{box.height}')

    for child in box.children:
        _format_box(child, indent_level + 1, lines)

    for line in box.lines:
        child_indent = '  ' * (indent_level + 1)
        lines.append(f'{child_indent}LINE {line.x},{line.y} {line.width}x{line.height} "{line.text}"')


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def main():
    if len(sys.argv) < 2:
        return

    filepath = sys.argv[1]
    viewport_width = 800
    if '--width' in sys.argv:
        idx = sys.argv.index('--width')
        if idx + 1 < len(sys.argv):
            viewport_width = int(sys.argv[idx + 1])

    with open(filepath, 'r', encoding='utf-8') as f:
        html_text = f.read()

    root = parse_html(html_text)
    if not root.children:
        return

    _set_parents(root)
    resolve_styles(root)

    body_box = layout_document(root, viewport_width)
    if body_box is None:
        return

    format_output(body_box)


if __name__ == '__main__':
    main()

