def _get_inherited_font_size(el):
    # Check this element's own font-size first
    fs = getattr(el, 'styles', {}).get('font-size') if hasattr(el, 'styles') else None
    if fs is not None:
        return fs
    # Otherwise inherit from parent
    parent = getattr(el, '_parent_', None)
    if parent is None:
        return 16
    fs = parent.styles.get('font-size', 16)
    if fs is None:
        return _get_inherited_font_size(parent)
    return fs

